// Cloudflare Worker entry: serves the Next.js app built by OpenNext and runs the daily
// Supabase keep-alive (Supabase Free pauses a project after 7 days without activity).
// @ts-ignore: generated by `opennextjs-cloudflare build`
import openNextWorker from './.open-next/worker.js';

type Env = {
  NEXT_PUBLIC_SUPABASE_URL?: string;
  NEXT_PUBLIC_SUPABASE_ANON_KEY?: string;
};

type WaitUntil = { waitUntil(promise: Promise<unknown>): void };

async function pingSupabase(env: Env) {
  const url = env.NEXT_PUBLIC_SUPABASE_URL;
  const key = env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
  if (!url || !key) {
    console.error('keep-alive: Supabase variables are missing');
    return;
  }
  // Count-only request: registers activity without reading any umat data.
  const res = await fetch(`${url}/rest/v1/events?select=id`, {
    method: 'HEAD',
    headers: { apikey: key, Authorization: `Bearer ${key}`, Prefer: 'count=exact' }
  });
  console.log(`keep-alive: Supabase responded ${res.status} (${res.headers.get('content-range') ?? 'no count'})`);
}

export default {
  fetch: openNextWorker.fetch,
  async scheduled(_controller: unknown, env: Env, ctx: WaitUntil) {
    ctx.waitUntil(pingSupabase(env));
  }
};
